<?php
namespace App\Http\Controllers\Api\V1; use App\Domain\Finance\Services\VendorResolver;use App\Http\Controllers\Controller;use App\Models\VendorTaxProfile;use App\Models\TaxClass;use Illuminate\Http\{JsonResponse,Request};use Illuminate\Support\Str; class SellerTaxController extends Controller { public function classes(Request $r):JsonResponse{return response()->json(['data'=>TaxClass::query()->where('status','active')->orderBy('name')->get()->map(/** Inline callback for this operation. */ fn($c)=>['id'=>$c->public_id,'code'=>$c->code,'name'=>$c->name,'default'=>$c->is_default])->all()]);} public function __construct(private readonly VendorResolver $vendors){} public function show(Request $r):JsonResponse{$v=$this->vendors->forUser($r->user());$p=VendorTaxProfile::query()->where('vendor_id',$v->id)->first();return response()->json(['data'=>['vendor'=>$v->name,'profile'=>$p?$this->row($p):null]]);} public function update(Request $r):JsonResponse{$v=$this->vendors->forUser($r->user());$d=$r->validate(['registeredName'=>'required|string|max:190','taxIdentifier'=>'nullable|string|max:120','registrationCountryCode'=>'required|string|size:2','priceIncludesTax'=>'required|boolean']);$existing=VendorTaxProfile::query()->where('vendor_id',$v->id)->first();if($existing?->status==='active')abort(409,'Verified tax profile changes require marketplace compliance review.');$p=$existing?:new VendorTaxProfile(['vendor_id'=>$v->id]);$p->public_id=$p->public_id?:((string)Str::ulid());$p->registered_name=$d['registeredName'];if(!empty($d['taxIdentifier'])){$p->tax_identifier=$d['taxIdentifier'];$p->tax_identifier_last4=substr(preg_replace('/\s+/','',$d['taxIdentifier']),-4);} $p->registration_country_code=strtoupper($d['registrationCountryCode']);$p->price_includes_tax=(bool)$d['priceIncludesTax'];$p->status='pending';$p->verified_at=null;$p->verified_by_user_id=null;$p->save();return response()->json(['data'=>$this->row($p)]);} private function row($p):array{return ['id'=>$p->public_id,'status'=>$p->status,'registeredName'=>$p->registered_name,'taxIdentifierLast4'=>$p->tax_identifier_last4,'registrationCountryCode'=>$p->registration_country_code,'collectionMode'=>$p->collection_mode,'priceIncludesTax'=>$p->price_includes_tax,'verifiedAt'=>$p->verified_at?->toIso8601String()];} }